def gpt4_cost(response):
    """Calculate the cost of a GPT-4 response."""
    input_tokens = response.usage.prompt_tokens
    output_tokens = response.usage.completion_tokens
    return (input_tokens * 0.01) + (output_tokens * 0.03)

