def prepare_context(self, text):
    if len(text) > self.model.config.max_position_embeddings - 2:
        text = text[:self.model.config.max_position_embeddings - 2]
    return [self.tokenizer.encode(text, add_special_tokens=False)]

def _process_llm_result(self, llm_output: str) -> dict[str, Any]:
    json_str = llm_output.split('```json\n')[1].split('\n```')[0]
    return json.loads(json_str)

def _parse_json(self):
    while True:
        chunk = self._read_chunk()
        if chunk is None:
            break
        try:
            json_data = json.loads(chunk)
            yield json_data
        except json.JSONDecodeError:
            continue
